-- Question bank: eight system design exercises with vetted reference answers.
--
-- The exercises are drawn from "The System Design Primer" by Donne Martin
-- (https://github.com/donnemartin/system-design-primer), licensed CC BY 4.0
-- (https://creativecommons.org/licenses/by/4.0/). The prompts, answers and diagrams below are our own rewrite and
-- condensation, not copied text. Attribution is stored with each reference answer (reference_solution.attribution)
-- and listed in docs/third-party-notices.md.
--
-- Because every row has a reference_solution, sessions on these questions skip the paid Council step (PRD 6.3 / FR4).
-- reference_solution shape: { summary, diagram: { nodes: [{id,label,shape,x,y}], edges: [{id,source,target,label}] },
-- tradeoffs: [...], attribution: {...} }.
--
-- questions has row-level security FORCEd (V7) and its insert policy only admits community submissions, so the
-- migration (which runs as the table owner) lifts FORCE for the inserts and restores it straight after, in the same
-- transaction. The application role is never affected.

ALTER TABLE questions NO FORCE ROW LEVEL SECURITY;

INSERT INTO questions (slug, title, prompt, source, status, reference_solution) VALUES
('primer-pastebin',
 'Design a text-sharing service like Pastebin',
 'Design a service where anyone can paste a block of text and get back a short random link; anyone with the link can read the text. A paste can optionally expire, expired pastes must be cleaned up, and the service tracks monthly visit counts per paste. Assume 10 million users, about 10 million new pastes and 100 million reads per month (read-heavy, 10:1), roughly 1 KB per paste, anonymous users only, analytics that need not be real-time, and links that must open quickly.',
 'SEED', 'APPROVED',
 $ref$
{"summary":"Clients reach a reverse proxy that sends writes to a Write API and reads to a Read API. A write generates a unique 7-character link (hash of random data or user+time, base62-encoded, collision-checked), stores the metadata row (link, expiry, created time, path to content) in a SQL database keyed on the link, and puts the text in an object store. A read looks the link up (cache first, then SQL), checks expiry, and streams the text from the object store. Visits are appended to access logs; a batch job aggregates them into monthly counts. A periodic job deletes expired rows and objects. 62^7 links comfortably covers ~360 million pastes over three years. Load is ~4 writes/s and ~40 reads/s on average, so a single database is enough at first; scale reads with replicas and a cache, and shard by link when needed.","diagram":{"nodes":[{"id":"n1","label":"Client","shape":"client","x":60,"y":180},{"id":"n2","label":"Web server (reverse proxy)","shape":"component","x":290,"y":180},{"id":"n3","label":"Write API","shape":"component","x":520,"y":50},{"id":"n4","label":"Read API","shape":"component","x":520,"y":310},{"id":"n5","label":"SQL database (link, expiry, content path)","shape":"datastore","x":750,"y":50},{"id":"n6","label":"Object store (paste text)","shape":"datastore","x":750,"y":180},{"id":"n7","label":"Memory cache (hot pastes)","shape":"datastore","x":750,"y":310},{"id":"n8","label":"Access logs","shape":"datastore","x":980,"y":310},{"id":"n9","label":"Analytics job (monthly visits)","shape":"component","x":980,"y":440},{"id":"n10","label":"Expiry cleanup job","shape":"component","x":980,"y":50}],"edges":[{"id":"e1","source":"n1","target":"n2","label":"create / view paste"},{"id":"e2","source":"n2","target":"n3","label":"create"},{"id":"e3","source":"n2","target":"n4","label":"view"},{"id":"e4","source":"n3","target":"n5","label":"link + metadata"},{"id":"e5","source":"n3","target":"n6","label":"paste text"},{"id":"e6","source":"n4","target":"n7","label":"lookup"},{"id":"e7","source":"n4","target":"n5","label":"on cache miss"},{"id":"e8","source":"n4","target":"n6","label":"fetch text"},{"id":"e9","source":"n4","target":"n8","label":"record visit"},{"id":"e10","source":"n9","target":"n8","label":"aggregate"},{"id":"e11","source":"n9","target":"n5","label":"write monthly stats"},{"id":"e12","source":"n10","target":"n5","label":"find expired"},{"id":"e13","source":"n10","target":"n6","label":"delete text"}]},"tradeoffs":["Link generation: hash + base62 and truncate (collisions must be checked) versus a pre-generated key service or counter (no collisions, extra moving part).","SQL as a large hash table versus a key-value store: SQL gives indexes and familiarity, a KV store scales writes more easily; at 4 writes/s either works.","Object store for text versus a database column: cheaper and simpler to scale, one more hop on reads; cache hot pastes to hide it.","Expiry: check on read (lazy) so expired pastes are never served, and delete in a background job so storage is reclaimed.","Analytics is batch because it need not be real-time; streaming would cost more for no stated benefit.","Scaling: read replicas and cache first, then shard SQL by link; keep the Read API stateless behind a load balancer."],"attribution":{"name":"The System Design Primer","author":"Donne Martin","url":"https://github.com/donnemartin/system-design-primer","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Question and answer rewritten and condensed; diagram redrawn."}}
$ref$::jsonb),
('primer-twitter-timeline',
 'Design a microblog timeline and search',
 'Design the core of a microblogging service. Users post short messages with optional media; followers see them in a home timeline, anyone can view a user''s own timeline, and users can search by keyword. Posting must be fast even for accounts with millions of followers, and reads vastly outnumber writes. Assume 100 million active users, 500 million posts per day with an average fan-out of 10, about 100,000 timeline reads per second and 4,000 searches per second, and high availability.',
 'SEED', 'APPROVED',
 $ref$
{"summary":"A Write API stores the post in a SQL store (the author's own timeline) and media in an object store, then hands it to a Fan-out Service. The fan-out asks the User Graph Service for the author's followers and pushes the post id into each follower's home timeline in a memory cache (a capped list per user), indexes it in the Search Index Service, and queues notifications for the Notification Service. Reading the home timeline is a Timeline Service call that reads the precomputed cached list, fetches post bodies, and merges in posts from celebrity accounts at read time. Fan-out on write costs O(followers) per post (~60,000 deliveries/s here), so accounts with millions of followers use fan-out on read instead (hybrid). Search is served from a sharded index fed asynchronously.","diagram":{"nodes":[{"id":"n1","label":"Client","shape":"client","x":60,"y":180},{"id":"n2","label":"Web server (reverse proxy)","shape":"component","x":290,"y":180},{"id":"n3","label":"Write API","shape":"component","x":520,"y":50},{"id":"n4","label":"Read API","shape":"component","x":520,"y":310},{"id":"n5","label":"SQL store (user timelines)","shape":"datastore","x":750,"y":50},{"id":"n6","label":"Object store (media)","shape":"datastore","x":750,"y":180},{"id":"n7","label":"Fan-out service","shape":"component","x":980,"y":50},{"id":"n8","label":"User graph service","shape":"component","x":1210,"y":50},{"id":"n9","label":"Timeline service","shape":"component","x":750,"y":310},{"id":"n10","label":"Memory cache (home timelines)","shape":"datastore","x":980,"y":310},{"id":"n11","label":"Search index service","shape":"component","x":1210,"y":180},{"id":"n12","label":"Queue","shape":"component","x":980,"y":180},{"id":"n13","label":"Notification service","shape":"component","x":1210,"y":310}],"edges":[{"id":"e1","source":"n1","target":"n2","label":"post / read / search"},{"id":"e2","source":"n2","target":"n3","label":"post"},{"id":"e3","source":"n2","target":"n4","label":"read, search"},{"id":"e4","source":"n3","target":"n5","label":"store post"},{"id":"e5","source":"n3","target":"n6","label":"media"},{"id":"e6","source":"n3","target":"n7","label":"new post"},{"id":"e7","source":"n7","target":"n8","label":"get followers"},{"id":"e8","source":"n7","target":"n10","label":"push to home timelines"},{"id":"e9","source":"n7","target":"n11","label":"index post"},{"id":"e10","source":"n7","target":"n12","label":"notify"},{"id":"e11","source":"n12","target":"n13","label":"push / email"},{"id":"e12","source":"n4","target":"n9","label":"home timeline"},{"id":"e13","source":"n9","target":"n10","label":"read list"},{"id":"e14","source":"n9","target":"n5","label":"load posts"},{"id":"e15","source":"n4","target":"n11","label":"keyword query"}]},"tradeoffs":["Fan-out on write makes reads fast but costs O(followers) per post; fan-out on read is cheap to write but slow to read. A hybrid handles celebrities.","Only keep timelines in memory for recently active users and rebuild on demand for the rest; the cache is capped per user.","Posts are eventually consistent across followers; a few seconds of delay is acceptable and buys write throughput.","SQL for a user's own posts works at first; shard by user id as volume grows, or move to a wide-column store.","Search is a separate, asynchronously updated, sharded index; do not query the primary store for it.","Notifications go through a queue so a slow push provider never blocks posting."],"attribution":{"name":"The System Design Primer","author":"Donne Martin","url":"https://github.com/donnemartin/system-design-primer","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Question and answer rewritten and condensed; diagram redrawn."}}
$ref$::jsonb),
('primer-web-crawler',
 'Design a web crawler and search backend',
 'Design a web crawler that visits about 1 billion links, refreshing them roughly weekly (about 4 billion fetches a month, ~500 KB per page), builds a reverse index of words to pages, and stores a static title and snippet for each page. A user then enters a search term and gets matching pages with titles and snippets. The crawler must not get stuck in loops, search results must be fast (about 40,000 searches per second), and the service must be highly available. Do not use an existing crawler or search engine.',
 'SEED', 'APPROVED',
 $ref$
{"summary":"A ranked frontier (a sorted set in a key-value store) holds links to crawl. Crawler workers repeatedly take the top link, check a crawled-links store for a page with a similar signature, and if the page is new fetch it, then queue one job for the Reverse Index Service and one for the Document Service (title and snippet), store the page's signature, and remove it from the frontier. A page that looks like one already seen has its priority lowered, which breaks cycles and duplicate content. Each page carries a last-crawled timestamp; popular or frequently changing pages are re-queued sooner, and robots.txt limits politeness per host. For search, a Query API cleans and normalises the query, asks the Reverse Index Service for ranked matches, and asks the Document Service for titles and snippets.","diagram":{"nodes":[{"id":"n1","label":"Client","shape":"client","x":60,"y":310},{"id":"n2","label":"Web server (reverse proxy)","shape":"component","x":290,"y":310},{"id":"n3","label":"Query API","shape":"component","x":520,"y":310},{"id":"n4","label":"Reverse index service","shape":"component","x":750,"y":310},{"id":"n5","label":"Document service","shape":"component","x":750,"y":440},{"id":"n6","label":"Links to crawl (ranked frontier)","shape":"datastore","x":60,"y":50},{"id":"n7","label":"Crawler service","shape":"component","x":290,"y":50},{"id":"n8","label":"Crawled links + page signatures","shape":"datastore","x":520,"y":50},{"id":"n9","label":"Index job queue","shape":"component","x":750,"y":50},{"id":"n10","label":"Document job queue","shape":"component","x":750,"y":180}],"edges":[{"id":"e1","source":"n1","target":"n2","label":"search term"},{"id":"e2","source":"n2","target":"n3","label":"query"},{"id":"e3","source":"n3","target":"n4","label":"find ranked matches"},{"id":"e4","source":"n3","target":"n5","label":"titles + snippets"},{"id":"e5","source":"n6","target":"n7","label":"top-ranked link"},{"id":"e6","source":"n7","target":"n8","label":"similar page already seen?"},{"id":"e7","source":"n7","target":"n9","label":"build index entry"},{"id":"e8","source":"n7","target":"n10","label":"build title + snippet"},{"id":"e9","source":"n9","target":"n4","label":"update index"},{"id":"e10","source":"n10","target":"n5","label":"store snippet"}]},"tradeoffs":["Duplicate URLs are cheap to remove (sort/unique, or MapReduce at this size); duplicate content needs a similarity signature (shingling with Jaccard, simhash, or cosine).","A ranked frontier prioritises popular sites but must also enforce per-host politeness, robots.txt and crawl-delay.","Partition the frontier and workers by host so one site is only fetched by one worker at a time.","Freshness: re-crawl on a default schedule, faster for pages observed to change often; learn change rates from history.","Storage is huge (about 2 PB of new page content a month); keep raw pages in cheap object storage and only indexes hot.","Spider traps and infinite URL spaces need depth limits and signature checks, not just URL de-duplication."],"attribution":{"name":"The System Design Primer","author":"Donne Martin","url":"https://github.com/donnemartin/system-design-primer","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Question and answer rewritten and condensed; diagram redrawn."}}
$ref$::jsonb),
('primer-personal-finance',
 'Design a personal finance aggregator like Mint',
 'Design a service where users link their bank and card accounts, the service pulls their transactions daily, categorises each one (the user can override), totals spending per category per month, and lets users set budgets and notifies them as they approach or pass a limit. Assume 10 million users, 30 million linked accounts, 5 billion transactions a month, daily refresh only for users active in the last 30 days, notifications that need not be instant, and high availability. Writes dominate reads.',
 'SEED', 'APPROVED',
 $ref$
{"summary":"Linking an account is a small write to a SQL database through an Accounts API. Pulling transactions is slow and external, so the API puts a job on a queue (on first link, on manual refresh, and daily for recently active users). A Transaction Extraction Service takes jobs, fetches transactions from the financial institution, keeps the raw responses in an object store, and runs each transaction through the Category Service (seller to category, with user overrides taking precedence and no automatic re-categorisation). It writes categorised rows to a transactions table and updates a monthly_spending aggregate; the Budget Service compares totals with budgets and asks the Notification Service (via a queue) to alert users. At ~2,000 transactions/s the transactions table is the pressure point: index by user and date and shard by user id.","diagram":{"nodes":[{"id":"n1","label":"Client","shape":"client","x":60,"y":180},{"id":"n2","label":"Web server (reverse proxy)","shape":"component","x":290,"y":180},{"id":"n3","label":"Accounts API","shape":"component","x":520,"y":180},{"id":"n4","label":"SQL database (accounts, transactions, monthly_spending)","shape":"datastore","x":750,"y":50},{"id":"n5","label":"Job queue","shape":"component","x":750,"y":180},{"id":"n6","label":"Transaction extraction service","shape":"component","x":980,"y":180},{"id":"n7","label":"Financial institution (external)","shape":"component","x":1210,"y":180},{"id":"n8","label":"Object store (raw responses)","shape":"datastore","x":1210,"y":50},{"id":"n9","label":"Category service","shape":"component","x":980,"y":310},{"id":"n10","label":"Budget service","shape":"component","x":1210,"y":310},{"id":"n11","label":"Notification service","shape":"component","x":980,"y":440}],"edges":[{"id":"e1","source":"n1","target":"n2","label":"link account / view spending"},{"id":"e2","source":"n2","target":"n3","label":"request"},{"id":"e3","source":"n3","target":"n4","label":"store account"},{"id":"e4","source":"n3","target":"n5","label":"extract job"},{"id":"e5","source":"n5","target":"n6","label":"next job"},{"id":"e6","source":"n6","target":"n7","label":"fetch transactions"},{"id":"e7","source":"n6","target":"n8","label":"raw log"},{"id":"e8","source":"n6","target":"n9","label":"categorise"},{"id":"e9","source":"n6","target":"n4","label":"transactions + monthly totals"},{"id":"e10","source":"n6","target":"n10","label":"check budgets"},{"id":"e11","source":"n10","target":"n11","label":"near / over budget"}]},"tradeoffs":["Asynchronous extraction through a queue hides slow bank calls and allows retries, at the cost of eventual freshness and more moving parts.","Refresh only recently active users daily to cap external calls; refresh others on demand.","Categories come from a seller-to-category map plus user overrides; re-categorising old data automatically would surprise users.","Pre-aggregate monthly totals at write time to keep reads cheap; recompute from raw transactions if a category changes.","Shard transactions by user id and index by user and date; consider cold-storage for old months.","Bank credentials and tokens are highly sensitive: use an aggregator or vault, encrypt at rest, never log them."],"attribution":{"name":"The System Design Primer","author":"Donne Martin","url":"https://github.com/donnemartin/system-design-primer","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Question and answer rewritten and condensed; diagram redrawn."}}
$ref$::jsonb),
('primer-social-graph-path',
 'Design shortest-path search for a social network',
 'Design the backend that shows a user the shortest chain of friends between themselves and someone they search for. Assume 100 million users with about 50 friends each (5 billion friendships, unweighted), 1 billion searches a month, a graph too large for one machine, and high availability. Do not rely on a dedicated graph database; build it from ordinary services.',
 'SEED', 'APPROVED',
 $ref$
{"summary":"Users are sharded across Person Servers, each holding profiles and friend-id lists for its shard. A Lookup Service maps a user id to the Person Server that owns it. The Search API forwards a request to the User Graph Service, which runs a breadth-first search: start from the searcher, fetch their friend ids from the owning Person Server, and keep expanding level by level, using the Lookup Service to find each next server. Each hop can be a network call, so batch lookups per server, cache person records and partial traversals in a memory cache, run a bidirectional BFS from both ends, and cap the search by hops or time before asking the user whether to continue. Average load is only ~400 searches/s but each search can touch many servers.","diagram":{"nodes":[{"id":"n1","label":"Client","shape":"client","x":60,"y":180},{"id":"n2","label":"Web server (reverse proxy)","shape":"component","x":290,"y":180},{"id":"n3","label":"Search API","shape":"component","x":520,"y":180},{"id":"n4","label":"User graph service (BFS)","shape":"component","x":750,"y":180},{"id":"n5","label":"Lookup service (user id -> server)","shape":"component","x":980,"y":50},{"id":"n6","label":"Person servers (sharded users + friend lists)","shape":"datastore","x":980,"y":310},{"id":"n7","label":"Memory cache (people, partial paths)","shape":"datastore","x":750,"y":440}],"edges":[{"id":"e1","source":"n1","target":"n2","label":"who is the path to X?"},{"id":"e2","source":"n2","target":"n3","label":"search"},{"id":"e3","source":"n3","target":"n4","label":"find shortest path"},{"id":"e4","source":"n4","target":"n5","label":"which server holds this user?"},{"id":"e5","source":"n4","target":"n6","label":"get friend ids"},{"id":"e6","source":"n4","target":"n7","label":"cached people / traversals"}]},"tradeoffs":["Plain BFS is correct for an unweighted graph but touches an exponentially growing frontier; bidirectional BFS cuts the work dramatically.","Shard by user id (even spread) or by location (friends are often co-located, fewer cross-server hops); location can create hot shards.","Every hop may cross machines: batch friend lookups per server and cache hot people and partial results.","The Lookup Service is on every request's critical path: replicate it and cache its answers.","Precompute popular or partial traversals offline into a NoSQL store when freshness allows.","Bound the search (hops or time) so a distant or unreachable target cannot tie up the cluster."],"attribution":{"name":"The System Design Primer","author":"Donne Martin","url":"https://github.com/donnemartin/system-design-primer","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Question and answer rewritten and condensed; diagram redrawn."}}
$ref$::jsonb),
('primer-search-query-cache',
 'Design a cache for recent search queries',
 'Design a key-value cache that stores the results of the most recent web search queries so popular searches are answered without hitting the index. Assume 10 million users and 10 billion queries a month (~4,000 requests per second), about 270 bytes per cached result, very uneven traffic, limited cache memory, low latency between machines, and high availability. Explain what is evicted and how entries stay fresh.',
 'SEED', 'APPROVED',
 $ref$
{"summary":"The Query API cleans and normalises the query (strip markup, tokenise, fix typos, lower-case) and uses it as the key into a memory cache. On a hit it moves the entry to the front of the LRU order and returns it. On a miss it asks the Reverse Index Service for ranked matches and the Document Service for titles and snippets, stores the result at the front of the cache, and evicts from the tail when full. The classic structure is a hash map from query to a node in a doubly linked list, giving O(1) lookup, move-to-front and eviction. Staleness is bounded with a time-to-live, and entries can also be dropped when pages change or ranks move. At scale the cache is partitioned across machines by key (consistent hashing) and replicated.","diagram":{"nodes":[{"id":"n1","label":"Client","shape":"client","x":60,"y":180},{"id":"n2","label":"Web server (reverse proxy)","shape":"component","x":290,"y":180},{"id":"n3","label":"Query API","shape":"component","x":520,"y":180},{"id":"n4","label":"Memory cache (LRU, TTL)","shape":"datastore","x":750,"y":50},{"id":"n5","label":"Reverse index service","shape":"component","x":750,"y":180},{"id":"n6","label":"Document service","shape":"component","x":750,"y":310}],"edges":[{"id":"e1","source":"n1","target":"n2","label":"search"},{"id":"e2","source":"n2","target":"n3","label":"query"},{"id":"e3","source":"n3","target":"n4","label":"lookup / store"},{"id":"e4","source":"n3","target":"n5","label":"on miss: find matches"},{"id":"e5","source":"n3","target":"n6","label":"on miss: titles + snippets"}]},"tradeoffs":["LRU suits skewed traffic where recent equals popular; LFU keeps long-term favourites but adapts slowly.","TTL is simple and bounds staleness; explicit invalidation is fresher but needs to know which queries a change affects.","Cache-aside keeps the cache optional and simple; write-through is not useful here because results come from a pipeline.","Shard the cache with consistent hashing so adding a node moves little data; replicate to survive a node loss.","A cold or restarted cache sends a burst to the index: warm it, rate-limit misses, and collapse duplicate in-flight lookups.","Size memory from the numbers: 270 bytes per entry, and hit ratio rises quickly because traffic is skewed."],"attribution":{"name":"The System Design Primer","author":"Donne Martin","url":"https://github.com/donnemartin/system-design-primer","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Question and answer rewritten and condensed; diagram redrawn."}}
$ref$::jsonb),
('primer-sales-rank',
 'Design a best-sellers by category ranking',
 'Design the component of an online store that shows the past week''s best-selling products in each category. Assume 10 million products, 1,000 categories, 1 billion transactions a month, 100 billion reads a month (100:1 read to write), results refreshed at least hourly, products that can sit in several categories, and high availability. Only design the ranking, not the whole store.',
 'SEED', 'APPROVED',
 $ref$
{"summary":"The Sales API appends every transaction to log files kept in an object store. An hourly Sales Rank Service runs a MapReduce job over the last week's logs: first map and reduce to the total quantity per (category, product), then a distributed sort per category. The ranked lists are written to a sales_rank table in a SQL database indexed by category and rank. Readers go through a Read API that serves the top products for a category from a memory cache (backed by the table), because reads outnumber writes 100 to 1 and the data changes only hourly. Popular categories can be refreshed more often. Rank results can be replicated to read replicas or a CDN-cached API for global reads.","diagram":{"nodes":[{"id":"n1","label":"Client","shape":"client","x":60,"y":180},{"id":"n2","label":"Web server (reverse proxy)","shape":"component","x":290,"y":180},{"id":"n3","label":"Read API","shape":"component","x":520,"y":310},{"id":"n4","label":"Memory cache (top products per category)","shape":"datastore","x":750,"y":310},{"id":"n5","label":"SQL database (sales_rank)","shape":"datastore","x":980,"y":310},{"id":"n6","label":"Sales API (records transactions)","shape":"component","x":520,"y":50},{"id":"n7","label":"Object store (transaction logs)","shape":"datastore","x":750,"y":50},{"id":"n8","label":"Sales rank service (hourly MapReduce)","shape":"component","x":980,"y":50}],"edges":[{"id":"e1","source":"n1","target":"n2","label":"view best sellers"},{"id":"e2","source":"n2","target":"n3","label":"read ranking"},{"id":"e3","source":"n3","target":"n4","label":"top N"},{"id":"e4","source":"n3","target":"n5","label":"on miss"},{"id":"e5","source":"n6","target":"n7","label":"append transaction log"},{"id":"e6","source":"n8","target":"n7","label":"read last week's logs"},{"id":"e7","source":"n8","target":"n5","label":"write ranked lists"}]},"tradeoffs":["Batch (hourly MapReduce/Spark) matches the freshness requirement and is simple; a streaming count would be fresher but costs more to run and keep correct.","A product in several categories is counted once per category in the map step.","Reads are 100x writes: cache the ranked lists, use read replicas, and serve through a CDN where possible.","Rolling week windows can be built from hourly or daily partial sums so each run does not re-read seven days.","Hot products and categories skew the reduce step; split heavy keys and combine locally first.","Keep the previous ranking available if a run fails, rather than showing nothing."],"attribution":{"name":"The System Design Primer","author":"Donne Martin","url":"https://github.com/donnemartin/system-design-primer","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Question and answer rewritten and condensed; diagram redrawn."}}
$ref$::jsonb),
('primer-scale-to-millions',
 'Design a system that scales from one user to millions',
 'You are running a web application with relational data that must grow from a handful of users to tens of millions (about 400 writes and 40,000 reads per second at the top, ~1 KB per write). Describe how the architecture evolves stage by stage: what you start with, what breaks next, and what you add at each step to stay fast and highly available. Explain how you decide when to scale and what each change costs.',
 'SEED', 'APPROVED',
 $ref$
{"summary":"Start with one box (web server and database) and basic monitoring; scale vertically while it is cheap. When that stops being enough, separate the tiers: move the database off, keep static files in an object store behind a CDN, and run several stateless web/API servers behind a load balancer with DNS in front. Add a memory cache for hot reads and a database primary with read replicas (reads are 100x writes); push slow work such as emails and image processing to queues and background workers. As the primary becomes the limit, federate or shard the data and move suitable parts to NoSQL, add automatic scaling across multiple availability zones, and keep measuring: load-test, find the bottleneck, fix it, repeat.","diagram":{"nodes":[{"id":"n1","label":"Client","shape":"client","x":60,"y":180},{"id":"n2","label":"DNS","shape":"component","x":290,"y":50},{"id":"n3","label":"CDN (static content)","shape":"component","x":290,"y":310},{"id":"n4","label":"Load balancer","shape":"component","x":520,"y":180},{"id":"n5","label":"Web / API servers (autoscaled, stateless)","shape":"component","x":750,"y":180},{"id":"n6","label":"Memory cache","shape":"datastore","x":980,"y":50},{"id":"n7","label":"Database primary (writes)","shape":"datastore","x":980,"y":180},{"id":"n8","label":"Read replicas","shape":"datastore","x":1210,"y":180},{"id":"n9","label":"Object store","shape":"datastore","x":980,"y":310},{"id":"n10","label":"Queue + background workers","shape":"component","x":750,"y":310},{"id":"n11","label":"Monitoring + load testing","shape":"component","x":520,"y":440}],"edges":[{"id":"e1","source":"n1","target":"n2","label":"resolve"},{"id":"e2","source":"n1","target":"n3","label":"static files"},{"id":"e3","source":"n1","target":"n4","label":"requests"},{"id":"e4","source":"n4","target":"n5","label":"spread load"},{"id":"e5","source":"n5","target":"n6","label":"hot reads"},{"id":"e6","source":"n5","target":"n7","label":"writes"},{"id":"e7","source":"n5","target":"n8","label":"reads"},{"id":"e8","source":"n7","target":"n8","label":"replicate"},{"id":"e9","source":"n5","target":"n9","label":"uploads"},{"id":"e10","source":"n5","target":"n10","label":"slow tasks"},{"id":"e11","source":"n3","target":"n9","label":"origin"},{"id":"e12","source":"n11","target":"n5","label":"metrics"}]},"tradeoffs":["Vertical scaling is simplest but gets expensive and leaves a single point of failure; horizontal scaling needs stateless servers.","Read replicas absorb read load but add replication lag, so read-your-writes needs care.","A cache cuts database load but adds invalidation complexity and a cold-start risk.","Federation (split by function) and sharding (split by key) raise write capacity but complicate joins and transactions.","SQL versus NoSQL: keep SQL while data is relational and consistency matters; move specific workloads to NoSQL when scale or shape demands it.","Always measure first: benchmark, profile, fix the actual bottleneck, then repeat."],"attribution":{"name":"The System Design Primer","author":"Donne Martin","url":"https://github.com/donnemartin/system-design-primer","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Question and answer rewritten and condensed; diagram redrawn."}}
